const keys={};let started=false,live=false,over=false,serveReady=true,playerScore=0,rivalScore=0,rally=1,last=performance.now(),elapsed=0,tideTime=12,tideSign=1,hitWindow=0,playerY=0,playerVy=0,aiHit=false,pointTimer=0,flashTimer=0;let dashCD=0,wellCD=0,wellTime=0,hitLock=0;const bpos=new THREE.Vector3(0,2.4,1.6),bvel=new THREE.Vector3();ball.position.copy(bpos);const DASH=4.5,WELL=8;
function overlay(on){ui.overlay.classList.toggle('hidden',!on)}
function message(title,sub){ui.title.textContent=title;ui.sub.textContent=sub;ui.message.style.opacity='1';flashTimer=2.2}
function startGame(){if(started)return;started=true;over=false;overlay(false);message('READY TO SERVE','Press enter or tap to launch the rally')}
document.querySelector('#startBtn').addEventListener('click',startGame);
function serve(){if(!started||live||over)return;live=true;serveReady=false;ui.message.style.opacity='0';bpos.set(player.g.position.x+.8,2.25,player.g.position.z);bvel.set(7.5,5.2,-.25);aiHit=false;}
function award(side){if(!live)return;live=false;pointTimer=2.15;if(side==='you'){playerScore++;message('POINT YOU','The tide is turning. Keep the pressure on.')}else{rivalScore++;message('POINT RIVAL','Reset. Read the current and return serve.')}ui.you.textContent=playerScore;ui.op.textContent=rivalScore;rally++;ui.rally.textContent=String(rally).padStart(2,'0');if(playerScore>=5||rivalScore>=5){over=true;pointTimer=2.8;message(playerScore>=5?'SET WON':'SET LOST',playerScore>=5?'Champion of the Neon Tidal Arena.':'The rival takes the set. Run it back.')} }
function pressHit(){if(!started){startGame();return}if(over){playerScore=0;rivalScore=0;rally=1;ui.you.textContent='0';ui.op.textContent='0';ui.rally.textContent='01';over=false;serveReady=true;pointTimer=0;message('READY TO SERVE','Press enter or tap to launch the rally');return}if(!live){serve();return}hitWindow=.32;if(hitLock>0)return;const d=player.g.position.distanceTo(bpos);if(d<2.1&&bpos.x<-.15&&bpos.y<4.2){hitLock=.42;const power=keys.e?1.18:1;const targetZ=-1.2;const dx=Math.max(2.4,Math.min(11,8.2-bpos.x));bvel.set(dx*power,Math.max(4.2,7.3-bpos.y*.55),((targetZ-bpos.z)*.65));player.arm.rotation.z=-1.35;player.paddle.scale.set(1.05,1.3,.16);hitWindow=0}}
function dash(){if(!started||!live||dashCD>0)return;dashCD=DASH;const direction=Math.sign((bpos.x-player.g.position.x)||1);player.g.position.x=THREE.MathUtils.clamp(player.g.position.x+direction*2.35,-8,-.72);player.g.position.z=THREE.MathUtils.clamp(player.g.position.z+(bpos.z-player.g.position.z)*.45,-3.6,3.6);player.g.userData.dash=1;if(player.g.position.distanceTo(bpos)<2.35&&bpos.x<0){hitLock=.4;bvel.set(Math.max(8,Math.abs(bvel.x)*1.12),Math.max(5.3,bvel.y+1.6),-1.6);message('JETSTREAM!','Surge hit · current disrupted');}}
function well(){if(!started||!live||wellCD>0)return;wellCD=WELL;wellTime=3.8;message('MOONPOOL','Gravity well active · ball bends to your return');}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup'].includes(e.key))e.preventDefault();keys[k]=true;if(e.repeat)return;if(k===' '||k==='w'||k==='arrowup'||k==='enter')pressHit();if(k==='e')dash();if(k==='q')well()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
// Accessible touch controls: hold to move, tap to activate skills / jump.
document.querySelectorAll('[data-hold]').forEach(btn=>{const k=btn.dataset.hold;const down=e=>{e.preventDefault();btn.classList.add('on');if(k==='space')pressHit();else if(k==='e')dash();else if(k==='q')well();else keys[k]=true};const up=e=>{e.preventDefault();btn.classList.remove('on');keys[k]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)});
renderer.domElement.addEventListener('pointerdown',()=>{if(!started)startGame();else if(!live||over)pressHit()});
function setCooldown(el,time,max){el.classList.toggle('ready',time<=0);el.querySelector('i').style.height=`${Math.max(0,100-time/max*100)}%`}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.035,(now-last)/1000);last=now;elapsed+=dt;
  // Player movement / jump
  let move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);player.g.position.x=THREE.MathUtils.clamp(player.g.position.x+move*7.2*dt,-8,-.72);if(keys.w&&!keys._jump){if(playerY<=.01)playerVy=7.1;keys._jump=true}if(!keys.w&&!keys[' '])keys._jump=false;if(keys[' ']&&!keys._spaceHeld){keys._spaceHeld=true;pressHit()}if(!keys[' '])keys._spaceHeld=false;playerVy-=17*dt;playerY=Math.max(0,playerY+playerVy*dt);if(playerY===0)playerVy=0;player.g.position.y=.28+playerY;player.body.rotation.z=move*.12;player.arm.rotation.z=THREE.MathUtils.damp(player.arm.rotation.z,-.42,8,dt);player.paddle.scale.y=THREE.MathUtils.damp(player.paddle.scale.y,1.12,8,dt);player.g.userData.dash=Math.max(0,(player.g.userData.dash||0)-dt*2);player.g.position.z=THREE.MathUtils.damp(player.g.position.z,1.6,2.5,dt);
  if(live){tideTime-=dt;if(tideTime<=0){tideTime=12;tideSign*=-1;message(tideSign>0?'TIDE SURGE →':'TIDE SURGE ←','The current has reversed');}const pulse=tideTime<2?1-tideTime/2:0;
    // Ballian physics with reversing tidal drift and active Moonpool curvature.
    bvel.y-=13.8*dt;if(wellTime>0){wellTime-=dt;const ax=-Math.sign(bpos.x||1)*5.5;bvel.x+=ax*dt;bvel.y+=Math.max(0,3.8-bpos.y)*dt;}else{bvel.x+=tideSign*1.05*dt*(1+pulse*.5);bvel.z+=Math.sin(elapsed*1.6)*.18*dt}
    bpos.addScaledVector(bvel,dt);bvel.multiplyScalar(Math.pow(.999,dt*60));
    // Keep the volley inside the lane. Side barriers softly deflect.
    if(Math.abs(bpos.z)>3.75){bpos.z=Math.sign(bpos.z)*3.75;bvel.z*=-.72}
    // Net collision on low trajectories.
    if(Math.abs(bpos.x)<.22&&bpos.y<3.02&&bpos.y>.55){bvel.x*=-.68;bpos.x=Math.sign(bpos.x||1)*.23;bvel.y=Math.max(1.1,bvel.y*.55)}
    // Rival tracks ball and returns with a short, readable reaction delay.
    const aiTarget=THREE.MathUtils.clamp(bpos.x+.8,.85,8);rival.g.position.x=THREE.MathUtils.damp(rival.g.position.x,aiTarget,3.6,dt);rival.g.position.z=THREE.MathUtils.damp(rival.g.position.z,THREE.MathUtils.clamp(bpos.z,-3,3),2.1,dt);
    const aiDist=rival.g.position.distanceTo(bpos);if(bpos.x>.3&&aiDist<1.62&&bpos.y<4.25&&bpos.y>.7&&!aiHit){aiHit=true;rival.arm.rotation.z=-1.35;bvel.set(-Math.max(6.6,Math.abs(bvel.x)*1.12),Math.max(4.1,6.6-bpos.y*.28),THREE.MathUtils.clamp((1.6-bpos.z)*.7,-2.5,2.5));}if(bpos.x<-.3)aiHit=false;rival.arm.rotation.z=THREE.MathUtils.damp(rival.arm.rotation.z,-.42,7,dt);rival.paddle.scale.y=THREE.MathUtils.damp(rival.paddle.scale.y,1.12,7,dt);
    if(bpos.y<.56){award(bpos.x<0?'rival':'you')}
    if(Math.abs(bpos.x)>10.4||bpos.y>12){award(bpos.x<0?'rival':'you')}
  }else if(pointTimer>0){pointTimer-=dt;if(pointTimer<=0){if(over){overlay(true);document.querySelector('#startBtn').textContent='PLAY AGAIN  →'}else{serveReady=true;message('READY TO SERVE','Press enter or tap to launch the rally')}}}
  dashCD=Math.max(0,dashCD-dt);wellCD=Math.max(0,wellCD-dt);hitLock=Math.max(0,hitLock-dt);setCooldown(document.querySelector('#dashUI'),dashCD,DASH);setCooldown(document.querySelector('#bubbleUI'),wellCD,WELL);
  ball.position.copy(bpos);ball.rotation.x+=dt*3;ball.rotation.z+=dt*2;ring.rotation.z+=dt*.15;current.position.set(0,.01,0);current.visible=live&&wellTime>0;current.rotation.y+=dt*.18;const pulseScale=1+Math.sin(elapsed*2)*.025;ring.scale.setScalar(pulseScale);
  ui.tide.style.width=`${((12-tideTime)/12)*100}%`;ui.wind.textContent=live?`CURRENT ${tideSign>0?'→':'←'} · ${Math.ceil(tideTime)}s`:`TIDE IN ${Math.ceil(tideTime)}s`;if(flashTimer>0){flashTimer-=dt;if(flashTimer<=0&&live)ui.message.style.opacity='0'}
